 @Test void downstreamFailureRollsBackRetentionBodyAndIntentAndRetriesOnlyKnownResult(){failDownstream=true;assertThrows(RuntimeException.class,this::apply);assertEquals(0,count("contents"));assertNull(new JdbcResultState(source).root(ROOT).resultHash());assertEquals("occupied",new JdbcWorkerState(source).slot().state());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE purpose='result'",Integer.class));failDownstream=false;assertEquals(Status.APPLIED,apply().status());assertEquals(1,sends);assertEquals(2,handlerCalls);}
